{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2129-05-05 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. I'm Dr. Lee, one of the surgical team. You're here today for your Puestow procedure to help with your chronic pancreatitis pain."
    },
    {
      "turn_number": 2,
      "time": "2129-05-05 08:02:00",
      "speaker": "Patient",
      "text": "Hi, thanks. I’ve been having a lot of pain lately, especially in the middle of my belly. Is this surgery going to fix that?"
    },
    {
      "turn_number": 3,
      "time": "2129-05-05 08:04:00",
      "speaker": "Doctor",
      "text": "Yes, the goal is to relieve the pain. We found that your main pancreatic duct is blocked by stones and is dilated. The Puestow procedure will open and drain that duct, which should reduce the pressure and pain."
    },
    {
      "turn_number": 4,
      "time": "2129-05-05 08:06:00",
      "speaker": "Patient",
      "text": "I remember having stones before. They took them out with a scope, right?"
    },
    {
      "turn_number": 5,
      "time": "2129-05-05 08:08:00",
      "speaker": "Doctor",
      "text": "That’s right. You’ve had several ERCPs in the past. But now the blockage is more extensive, and the duct is permanently narrowed. Surgery is the best option now to create a long-term drainage path."
    },
    {
      "turn_number": 6,
      "time": "2129-05-05 08:10:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense. Will I be asleep the whole time?"
    },
    {
      "turn_number": 7,
      "time": "2129-05-05 08:12:00",
      "speaker": "Doctor",
      "text": "Yes, you’ll be under general anesthesia. The surgery usually takes a few hours. We’ll also use an intraoperative ultrasound to help locate the duct and stones precisely."
    },
    {
      "turn_number": 8,
      "time": "2129-05-05 08:14:00",
      "speaker": "Patient",
      "text": "Sounds good. I’m ready to get this done."
    },
    {
      "turn_number": 9,
      "time": "2129-05-05 12:30:00",
      "speaker": "Doctor",
      "text": "Hi, it’s Dr. Lee again. The surgery went very well. We performed the Puestow with a Roux-en-Y drainage and used ultrasound to guide us. We removed two large stones from your pancreatic duct."
    },
    {
      "turn_number": 10,
      "time": "2129-05-05 12:32:00",
      "speaker": "Patient",
      "text": "That’s a relief. I feel groggy, but no pain yet."
    },
    {
      "turn_number": 11,
      "time": "2129-05-05 12:34:00",
      "speaker": "Doctor",
      "text": "You’re on a Dilaudid PCA pump for pain, so you can control it as needed. You have an NG tube to rest your stomach and a catheter for urine. We’ll remove those as you recover."
    },
    {
      "turn_number": 12,
      "time": "2129-05-05 12:36:00",
      "speaker": "Patient",
      "text": "How long will I be on the NG tube?"
    },
    {
      "turn_number": 13,
      "time": "2129-05-05 12:38:00",
      "speaker": "Doctor",
      "text": "Usually a few days. Once your bowel starts working again, we’ll remove it and start you on small sips of water."
    },
    {
      "turn_number": 14,
      "time": "2129-05-06 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your labs show your white count is high, which is expected after surgery. Your kidney function is stable, and we’re managing your blood sugar with insulin as needed."
    },
    {
      "turn_number": 15,
      "time": "2129-05-06 09:02:00",
      "speaker": "Patient",
      "text": "I’ve been feeling a little foggy. Is that normal?"
    },
    {
      "turn_number": 16,
      "time": "2129-05-06 09:04:00",
      "speaker": "Doctor",
      "text": "It could be from the pain meds. We’re watching that. We’re also giving you heparin shots and compression boots to prevent clots, given your history."
    },
    {
      "turn_number": 17,
      "time": "2129-05-06 09:06:00",
      "speaker": "Patient",
      "text": "I remember I had a DVT before. Glad you’re on top of that."
    },
    {
      "turn_number": 18,
      "time": "2129-05-07 10:15:00",
      "speaker": "Doctor",
      "text": "We’re adding methadone to your pain regimen because the Dilaudid alone wasn’t enough. It’s stronger and longer-lasting, which should help."
    },
    {
      "turn_number": 19,
      "time": "2129-05-07 10:17:00",
      "speaker": "Patient",
      "text": "Is methadone safe? I’ve heard it’s for addiction."
    },
    {
      "turn_number": 20,
      "time": "2129-05-07 10:19:00",
      "speaker": "Doctor",
      "text": "Yes, it’s used for addiction, but also for severe pain. We’ll use it short-term and taper it as you heal. The Chronic Pain Service will help manage the transition."
    },
    {
      "turn_number": 21,
      "time": "2129-05-08 08:30:00",
      "speaker": "Doctor",
      "text": "Great news — your NG tube is out. You can start with small sips of clear liquids. We’ll advance your diet slowly."
    },
    {
      "turn_number": 22,
      "time": "2129-05-08 08:32:00",
      "speaker": "Patient",
      "text": "I’m starving. Can I have broth?"
    },
    {
      "turn_number": 23,
      "time": "2129-05-08 08:34:00",
      "speaker": "Doctor",
      "text": "Yes, clear broth is perfect. We’ll see how you tolerate it and move to soft foods tomorrow if all goes well."
    },
    {
      "turn_number": 24,
      "time": "2129-05-08 08:36:00",
      "speaker": "Patient",
      "text": "And the catheter?"
    },
    {
      "turn_number": 25,
      "time": "2129-05-08 08:38:00",
      "speaker": "Doctor",
      "text": "It’s already out. You’ve been able to urinate on your own, which is great."
    },
    {
      "turn_number": 26,
      "time": "2129-05-09 09:00:00",
      "speaker": "Doctor",
      "text": "Your abdominal X-ray shows some dilated bowel loops. This is common after surgery — it’s called an ileus. It means your gut is still waking up."
    },
    {
      "turn_number": 27,
      "time": "2129-05-09 09:02:00",
      "speaker": "Patient",
      "text": "Is that dangerous?"
    },
    {
      "turn_number": 28,
      "time": "2129-05-09 09:04:00",
      "speaker": "Doctor",
      "text": "Not usually. We’re encouraging you to walk and use the incentive spirometer to help everything get moving. It should resolve in a day or two."
    },
    {
      "turn_number": 29,
      "time": "2129-05-10 14:00:00",
      "speaker": "Doctor",
      "text": "We did a CT scan because you had some trouble breathing when walking. It shows some fluid in your lungs, likely from aspiration, and a lymph node in your chest we need to check out later."
    },
    {
      "turn_number": 30,
      "time": "2129-05-10 14:02:00",
      "speaker": "Patient",
      "text": "Aspiration? How did that happen?"
    },
    {
      "turn_number": 31,
      "time": "2129-05-10 14:04:00",
      "speaker": "Doctor",
      "text": "Sometimes after surgery, especially with sedation, stomach contents can go into the lungs. It’s not uncommon. We’ll monitor it and make sure it clears."
    },
    {
      "turn_number": 32,
      "time": "2129-05-10 14:06:00",
      "speaker": "Patient",
      "text": "And the lymph node?"
    },
    {
      "turn_number": 33,
      "time": "2129-05-10 14:08:00",
      "speaker": "Doctor",
      "text": "It could be reactive from infection or inflammation. But we recommend a bronchoscopy later to rule out anything serious."
    },
    {
      "turn_number": 34,
      "time": "2129-05-11 10:00:00",
      "speaker": "Doctor",
      "text": "You had a brief episode yesterday that looked like a seizure. Neurology was consulted."
    },
    {
      "turn_number": 35,
      "time": "2129-05-11 10:02:00",
      "speaker": "Patient",
      "text": "I don’t remember that. Was it a real seizure?"
    },
    {
      "turn_number": 36,
      "time": "2129-05-11 10:04:00",
      "speaker": "Doctor",
      "text": "Neurology thinks it was a nonepileptic event, similar to pseudoseizures you’ve had before. They don’t recommend more testing. Psychiatry thinks the confusion was from the narcotics."
    },
    {
      "turn_number": 37,
      "time": "2129-05-11 10:06:00",
      "speaker": "Patient",
      "text": "So it’s not my epilepsy acting up?"
    },
    {
      "turn_number": 38,
      "time": "2129-05-11 10:08:00",
      "speaker": "Doctor",
      "text": "No, you’re still on your seizure meds, but this wasn’t a true seizure. We’re tapering the narcotics, and your mental clarity has improved."
    },
    {
      "turn_number": 39,
      "time": "2129-05-11 10:10:00",
      "speaker": "Patient",
      "text": "Good. I feel much more like myself today."
    },
    {
      "turn_number": 40,
      "time": "2129-05-12 09:30:00",
      "speaker": "Doctor",
      "text": "You’re doing really well. You’re on a regular diet, walking without help, and your pain is controlled with oral hydromorphone and gabapentin."
    },
    {
      "turn_number": 41,
      "time": "2129-05-12 09:32:00",
      "speaker": "Patient",
      "text": "Can I go home soon?"
    },
    {
      "turn_number": 42,
      "time": "2129-05-12 09:34:00",
      "speaker": "Doctor",
      "text": "Yes, likely tomorrow. We’ll send you home with pain meds, Viokase for digestion, and a nicotine patch since you’re trying to quit smoking."
    },
    {
      "turn_number": 43,
      "time": "2129-05-12 09:36:00",
      "speaker": "Patient",
      "text": "I appreciate that. What about my other meds?"
    },
    {
      "turn_number": 44,
      "time": "2129-05-12 09:38:00",
      "speaker": "Doctor",
      "text": "You’ll resume all your home medications — lisinopril, simvastatin, ziprasidone, omeprazole, and the others — unless we say otherwise."
    },
    {
      "turn_number": 45,
      "time": "2129-05-12 09:40:00",
      "speaker": "Patient",
      "text": "And the gabapentin?"
    },
    {
      "turn_number": 46,
      "time": "2129-05-12 09:42:00",
      "speaker": "Doctor",
      "text": "You’ll take it at bedtime for four days to help with nerve pain and then stop. We’re also giving you a short supply of hydromorphone for breakthrough pain."
    },
    {
      "turn_number": 47,
      "time": "2129-05-13 10:00:00",
      "speaker": "Doctor",
      "text": "Final plan: You’ll be discharged tomorrow morning. A home health nurse will check on you, and you’ll follow up with me and your PCP in two weeks."
    },
    {
      "turn_number": 48,
      "time": "2129-05-13 10:02:00",
      "speaker": "Patient",
      "text": "What should I watch for at home?"
    },
    {
      "turn_number": 49,
      "time": "2129-05-13 10:04:00",
      "speaker": "Doctor",
      "text": "Call us if you have increasing pain, redness or drainage from the incision, fever, or trouble breathing. No heavy lifting for a few weeks."
    },
    {
      "turn_number": 50,
      "time": "2129-05-13 10:06:00",
      "speaker": "Patient",
      "text": "Can I shower?"
    },
    {
      "turn_number": 51,
      "time": "2129-05-13 10:08:00",
      "speaker": "Doctor",
      "text": "Yes, you can shower. Gently wash the area and pat it dry. No baths or swimming until your follow-up."
    },
    {
      "turn_number": 52,
      "time": "2129-05-13 10:10:00",
      "speaker": "Patient",
      "text": "And driving?"
    },
    {
      "turn_number": 53,
      "time": "2129-05-13 10:12:00",
      "speaker": "Doctor",
      "text": "Not while on pain meds. Wait until you’re off them and cleared by your surgeon."
    },
    {
      "turn_number": 54,
      "time": "2129-05-13 10:14:00",
      "speaker": "Patient",
      "text": "Got it. I’ll take it slow."
    },
    {
      "turn_number": 55,
      "time": "2129-05-14 07:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared for discharge. You’re alert, eating well, and your vitals are stable."
    },
    {
      "turn_number": 56,
      "time": "2129-05-14 07:02:00",
      "speaker": "Patient",
      "text": "I’m ready to go home. Thank you for everything."
    },
    {
      "turn_number": 57,
      "time": "2129-05-14 07:04:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Remember to rest, keep walking, and follow up with your doctors. The home health nurse will visit tomorrow."
    },
    {
      "turn_number": 58,
      "time": "2129-05-14 07:06:00",
      "speaker": "Patient",
      "text": "I’ll do that. And I’ll schedule the bronchoscopy soon."
    },
    {
      "turn_number": 59,
      "time": "2129-05-14 07:08:00",
      "speaker": "Doctor",
      "text": "Excellent. Take care, and call us with any concerns."
    },
    {
      "turn_number": 60,
      "time": "2129-05-14 07:10:00",
      "speaker": "Patient",
      "text": "Will do. Thanks again."
    },
    {
      "turn_number": 61,
      "time": "2129-05-14 08:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check-in before you leave. Any last questions?"
    },
    {
      "turn_number": 62,
      "time": "2129-05-14 08:02:00",
      "speaker": "Patient",
      "text": "No, I think I’ve got it all. Meds, diet, incision care, follow-up."
    },
    {
      "turn_number": 63,
      "time": "2129-05-14 08:04:00",
      "speaker": "Doctor",
      "text": "Perfect. You’ve done great this week. Healing takes time, but you’re on the right track."
    },
    {
      "turn_number": 64,
      "time": "2129-05-14 08:06:00",
      "speaker": "Patient",
      "text": "I feel a lot better already. Hope the pain keeps improving."
    },
    {
      "turn_number": 65,
      "time": "2129-05-14 08:08:00",
      "speaker": "Doctor",
      "text": "It will. We’ll adjust your pain plan as needed. Don’t hesitate to call."
    },
    {
      "turn_number": 66,
      "time": "2129-05-14 08:10:00",
      "speaker": "Patient",
      "text": "I won’t. Thanks for explaining everything so clearly."
    },
    {
      "turn_number": 67,
      "time": "2129-05-14 08:12:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Take care, and we’ll see you soon."
    },
    {
      "turn_number": 68,
      "time": "2129-05-14 09:00:00",
      "speaker": "Patient",
      "text": "Doctor, one more thing — should I keep taking the nicotine patch?"
    },
    {
      "turn_number": 69,
      "time": "2129-05-14 09:02:00",
      "speaker": "Doctor",
      "text": "Yes, use it daily as prescribed. It can help with cravings. Let your PCP know how it’s going."
    },
    {
      "turn_number": 70,
      "time": "2129-05-14 09:04:00",
      "speaker": "Patient",
      "text": "Will do. I’m really trying to quit this time."
    },
    {
      "turn_number": 71,
      "time": "2129-05-14 09:06:00",
      "speaker": "Doctor",
      "text": "That’s great to hear. Support is available if you need it."
    },
    {
      "turn_number": 72,
      "time": "2129-05-14 09:08:00",
      "speaker": "Patient",
      "text": "I’ll keep that in mind."
    },
    {
      "turn_number": 73,
      "time": "2129-05-14 10:00:00",
      "speaker": "Doctor",
      "text": "Just confirming — you understand when to take your meds and when to call us?"
    },
    {
      "turn_number": 74,
      "time": "2129-05-14 10:02:00",
      "speaker": "Patient",
      "text": "Yes, hydromorphone only if needed, gabapentin at night for four days, and call if I have fever or wound issues."
    },
    {
      "turn_number": 75,
      "time": "2129-05-14 10:04:00",
      "speaker": "Doctor",
      "text": "Exactly. And no NSAIDs — stick to acetaminophen if you need extra pain relief."
    },
    {
      "turn_number": 76,
      "time": "2129-05-14 10:06:00",
      "speaker": "Patient",
      "text": "Got it. No ibuprofen."
    },
    {
      "turn_number": 77,
      "time": "2129-05-14 10:08:00",
      "speaker": "Doctor",
      "text": "You’ve got a good grasp on everything. We’re confident you’ll do well at home."
    },
    {
      "turn_number": 78,
      "time": "2129-05-14 10:10:00",
      "speaker": "Patient",
      "text": "Thanks for all your help."
    },
    {
      "turn_number": 79,
      "time": "2129-05-14 10:12:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care and rest well."
    },
    {
      "turn_number": 80,
      "time": "2129-05-14 11:00:00",
      "speaker": "Patient",
      "text": "Doctor, the nurse said I can leave soon. Just wanted to say goodbye."
    },
    {
      "turn_number": 81,
      "time": "2129-05-14 11:02:00",
      "speaker": "Doctor",
      "text": "Goodbye. We’ll see you in clinic soon. Stay safe."
    },
    {
      "turn_number": 82,
      "time": "2129-05-14 11:04:00",
      "speaker": "Patient",
      "text": "I will. Thank you."
    },
    {
      "turn_number": 83,
      "time": "2129-05-14 11:06:00",
      "speaker": "Doctor",
      "text": "Take care."
    },
    {
      "turn_number": 84,
      "time": "2129-05-14 11:08:00",
      "speaker": "Patient",
      "text": "Bye."
    },
    {
      "turn_number": 85,
      "time": "2129-05-14 11:10:00",
      "speaker": "Doctor",
      "text": "Have a safe trip home."
    }
  ],
  "summary": {
    "admission_start": "2129-05-05 08:00:00",
    "admission_end": "2129-05-14 12:40:00",
    "summary_paragraph": "A 50-year-old male with chronic pancreatitis, bipolar disorder, PTSD, and a history of alcohol abuse was admitted for a Puestow procedure due to obstructing pancreatic duct stones causing ductal dilation and severe pain. He underwent successful surgery with Roux-en-Y drainage and intraoperative ultrasound guidance. Post-operatively, he experienced inadequate pain control initially, which was managed by adding methadone and later transitioning to oral hydromorphone and gabapentin. He developed transient confusion and a single nonepileptic seizure-like episode on post-operative day 7, attributed to narcotics and managed with dose tapering. His diet advanced from NPO to regular, and he ambulated early. A CT scan revealed a right hilar lymph node requiring bronchoscopy and findings suggestive of aspiration. He was discharged home with home health services, on a regimen including pain medication, Viokase, and a nicotine patch, with follow-up planned with surgery and primary care.",
    "problems": [
      "Chronic pancreatitis",
      "Drug-induced delirium",
      "Other opiates and related narcotics causing adverse effects in therapeutic use",
      "Other specified diseases of pancreas",
      "Other chronic pain",
      "Other convulsions",
      "Bipolar disorder, unspecified",
      "Alcohol abuse, in remission",
      "Unspecified essential hypertension",
      "Other and unspecified hyperlipidemia",
      "Lumbago",
      "Posttraumatic stress disorder"
    ]
  }
}
